def _fetch_with_retry(self, max_retries: int = 3) -> dict[str, str]:
        for attempt in range(max_retries):
            try:
                return self._fetcher()
            except Exception as exc:
                if attempt == max_retries - 1:
                    if self._keys:
                        return self._keys  # Stale-if-error fallback
                    raise RuntimeError('JWKS fetch failed with empty cache') from exc
                time.sleep((0.1 * (2 ** attempt)) + random.uniform(0, 0.05))
        return self._keys
